GOLD_ITEM_NAME = 'Or'


def move_gold_to_wallet(apps, schema_editor):
    """L'or quitte l'inventaire pour devenir un solde sur le membre."""
    User = apps.get_model('users', 'User')
    UserInventory = apps.get_model('users', 'UserInventory')
    Item = apps.get_model('shop', 'Item')

    # Les membres qui ont déjà ouvert leur inventaire ont reçu l'or de départ.
    User.objects.filter(inventory__isnull=False).update(starting_gold_given=True)

    gold_items = list(Item.objects.filter(name=GOLD_ITEM_NAME))
    for row in (UserInventory.objects.filter(item__in=gold_items)
                .values('user_id').annotate(total=Sum('quantity'))):
        User.objects.filter(pk=row['user_id']).update(gold=row['total'] or 0)
    UserInventory.objects.filter(item__in=gold_items).delete()
    for item in gold_items:
        category = item.category
        item.delete()
        if not category.items.exists():
            category.delete()

    # Doublons éventuels : on fusionne les quantités sur une seule ligne.
    seen = {}
    for entry in UserInventory.objects.order_by('pk'):
        key = (entry.user_id, entry.item_id)
        if key in seen:
            keeper = seen[key]
            keeper.quantity += entry.quantity
            keeper.save(update_fields=['quantity'])
            entry.delete()
        else:
            seen[key] = entry


def wallet_back_to_inventory(apps, schema_editor):
    User = apps.get_model('users', 'User')
    UserInventory = apps.get_model('users', 'UserInventory')
    Item = apps.get_model('shop', 'Item')
    Category = apps.get_model('shop', 'Category')
    category, _ = Category.objects.get_or_create(name='Monnaie', defaults={'description': 'Monnaie du site'})
    gold_item, _ = Item.objects.get_or_create(
        name=GOLD_ITEM_NAME, defaults={'category': category, 'description': 'Monnaie utilisée sur le site'},
    )
    for user in User.objects.filter(starting_gold_given=True):
        UserInventory.objects.create(user=user, item=gold_item, quantity=user.gold)


